package com.oms.inventory;
import org.junit.jupiter.api.*;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;

class StockCareReholdTest {
 StockCareTest f;
 @BeforeAll static void start(){OrderStockTest.start();}
 @AfterAll static void stop(){OrderStockTest.stop();}
 @BeforeEach void seed(){f=new StockCareTest();f.setup();}
 Map<String,Object> command(String key,int q){return f.m("document_sn","CGTRESTORE","message_id",key,"actor","tester","lines",Collections.singletonList(f.m("line_key",1,"quantity",q)));}
 void stopped(){f.care.execute("VERIFY","reserve",f.reserve("CGTRESTORE","ZP",5));f.care.execute("VERIFY","post",f.post("CGTRESTORE","E1/M1",2));f.care.execute("VERIFY","release",f.m("document_sn","CGTRESTORE","message_id","STOP1","actor","tester"));}
 @Test void restoreKeepsReleaseHistoryAndOriginalPlanThenPostsRemaining(){stopped();f.care.execute("VERIFY","rehold",command("RESTORE1",3));f.care.execute("VERIFY","rehold",command("RESTORE1",3));assertEquals(11,f.n("SELECT total_stock FROM oms_inventory" ));assertEquals(5,f.n("SELECT available_stock FROM oms_inventory"));assertEquals(3,f.n("SELECT allocated_stock FROM oms_inventory"));assertEquals(8,f.n("SELECT quantity FROM oms_stock_care_line"));assertEquals(5,f.n("SELECT planned_quantity FROM oms_stock_care_line"));assertEquals(3,f.n("SELECT released_quantity FROM oms_stock_care_line"));f.care.execute("VERIFY","post",f.post("CGTRESTORE","E2/M1",3));assertEquals(8,f.n("SELECT total_stock FROM oms_inventory"));assertEquals(5,f.n("SELECT available_stock FROM oms_inventory"));assertEquals(5,f.n("SELECT consumed_quantity FROM oms_stock_care_line"));assertEquals(1,f.n("SELECT COUNT(*) FROM wms_inventory_change_history WHERE operation_type='RETURN_REHOLD'"));}
 @Test void multipleStopRestoreCyclesNeverResetConsumedOrReleased(){stopped();f.care.execute("VERIFY","rehold",command("R1",3));f.care.execute("VERIFY","post",f.post("CGTRESTORE","E2/M1",1));f.care.execute("VERIFY","release",f.m("document_sn","CGTRESTORE","message_id","STOP2","actor","tester"));f.care.execute("VERIFY","rehold",command("R2",2));assertEquals(5,f.n("SELECT released_quantity FROM oms_stock_care_line"));assertEquals(3,f.n("SELECT consumed_quantity FROM oms_stock_care_line"));assertEquals(10,f.n("SELECT quantity FROM oms_stock_care_line"));assertEquals(2,f.n("SELECT allocated_stock FROM oms_inventory"));assertThrows(IllegalArgumentException.class,()->f.care.execute("VERIFY","rehold",command("EXTRA",1)));}
 @Test void changedReplayAndOverPlanHaveNoEffect(){stopped();assertThrows(IllegalArgumentException.class,()->f.care.execute("VERIFY","rehold",command("R1",4)));f.care.execute("VERIFY","rehold",command("R1",2));assertThrows(IllegalArgumentException.class,()->f.care.execute("VERIFY","rehold",command("R1",3)));assertEquals(2,f.n("SELECT allocated_stock FROM oms_inventory"));}
 @Test void concurrentRestoresCannotDoubleHoldReleasedRemainder()throws Exception{stopped();ExecutorService pool=Executors.newFixedThreadPool(2);try{List<Callable<Boolean>> jobs=new ArrayList<>();for(String key:Arrays.asList("R1","R2"))jobs.add(()->{try{f.care.execute("VERIFY","rehold",command(key,3));return true;}catch(IllegalArgumentException e){return false;}});int success=0;for(Future<Boolean>r:pool.invokeAll(jobs))if(r.get())success++;assertEquals(1,success);assertEquals(3,f.n("SELECT allocated_stock FROM oms_inventory"));}finally{pool.shutdownNow();}}
 @Test void ordersOwnPriorityAfterRelease(){stopped();f.f.execute("register",f.f.command("90191",7,true));f.f.execute("reserve",f.f.command("90191",7,true));assertThrows(IllegalArgumentException.class,()->f.care.execute("VERIFY","rehold",command("R1",3)));assertEquals(0,f.n("SELECT allocated_stock FROM oms_inventory"));assertEquals(3,f.n("SELECT released_quantity FROM oms_stock_care_line"));}
 @Test void badRestorePreservesFrozenAndPhysicalBuckets(){f.care.execute("VERIFY","reserve",f.reserve("CGTRESTORE","CP",3));f.care.execute("VERIFY","post",f.post("CGTRESTORE","E1",1));f.care.execute("VERIFY","release",f.m("document_sn","CGTRESTORE","message_id","S1","actor","tester"));f.care.execute("VERIFY","rehold",command("R1",2));assertEquals(12,f.n("SELECT total_stock FROM oms_inventory"));assertEquals(10,f.n("SELECT available_stock FROM oms_inventory"));assertEquals(0,f.n("SELECT frozen_stock FROM oms_inventory"));assertEquals(2,f.n("SELECT allocated_stock FROM oms_inventory"));}
}
